import pytest

from evalmerge.normalize import (
    clamp_score,
    date_to_rfc3339,
    epoch_to_rfc3339,
    normalize_model,
    parse_score_text,
    parse_timestamp_mixed,
)


class TestNormalizeModel:
    @pytest.mark.parametrize(
        ("raw", "expected"),
        [
            ("Gemma-2 2B", "gemma-2-2b"),
            ("gemma-2-2b", "gemma-2-2b"),
            ("LLAMA-3  8b", "llama-3-8b"),
            ("Llama-3 8B", "llama-3-8b"),
            ("Mistral 7B", "mistral-7b"),
            ("  mixtral_8x7b  ", "mixtral-8x7b"),
            ("Model - X", "model-x"),
        ],
    )
    def test_variants(self, raw, expected):
        assert normalize_model(raw) == expected

    def test_idempotent(self):
        once = normalize_model("Gemma-2 2B")
        assert normalize_model(once) == once


class TestParseScoreText:
    def test_percentage(self):
        assert parse_score_text("87.5%") == pytest.approx(0.875)
        assert parse_score_text(" 92.0% ") == pytest.approx(0.92)

    def test_fraction(self):
        assert parse_score_text("0.91") == pytest.approx(0.91)
        assert parse_score_text("1.2") == pytest.approx(1.2)  # clamping is separate

    def test_unparseable(self):
        assert parse_score_text("") is None
        assert parse_score_text("n/a") is None
        assert parse_score_text("x%") is None


class TestTimestamps:
    def test_iso_with_z(self):
        assert parse_timestamp_mixed("2026-05-01T12:00:00Z") == "2026-05-01T12:00:00Z"

    def test_iso_with_offset_converted_to_utc(self):
        assert parse_timestamp_mixed("2026-05-01T14:00:00+02:00") == "2026-05-01T12:00:00Z"

    def test_us_style(self):
        assert parse_timestamp_mixed("05/01/2026 12:30") == "2026-05-01T12:30:00Z"

    def test_unparseable(self):
        assert parse_timestamp_mixed("not-a-timestamp") is None
        assert parse_timestamp_mixed("13/45/2026 99:99") is None
        assert parse_timestamp_mixed("") is None

    def test_epoch_seconds(self):
        assert epoch_to_rfc3339(1777636800) == "2026-05-01T12:00:00Z"

    def test_epoch_milliseconds(self):
        assert epoch_to_rfc3339(1777636800000) == "2026-05-01T12:00:00Z"

    def test_epoch_invalid(self):
        assert epoch_to_rfc3339(None) is None
        assert epoch_to_rfc3339("soon") is None
        assert epoch_to_rfc3339(True) is None

    def test_date_only_is_midnight_utc(self):
        assert date_to_rfc3339("2026-05-01") == "2026-05-01T00:00:00Z"
        assert date_to_rfc3339("2026-13-01") is None


class TestClampScore:
    def test_in_range_untouched(self):
        assert clamp_score(0.0) == (0.0, False)
        assert clamp_score(0.5) == (0.5, False)
        assert clamp_score(1.0) == (1.0, False)

    def test_clamped(self):
        assert clamp_score(1.5) == (1.0, True)
        assert clamp_score(-0.1) == (0.0, True)
